343	/// Moves line comments after the `default` keyword into the block statement:
344	///
345	/// ```javascript
346	/// switch (x) {
347	///     default: // comment
348	///     {
349	///         break;
350	///     }
351	/// ```
352	///
353	/// All other same line comments will use `Default` placement if they have a preceding node.
354	/// ```javascript
355	/// switch(x) {
356	///     default:
357	///         a(); // asd
358	///         break;
359	/// }
360	/// ```
361	///
362	/// All other comments become `Dangling` comments that are handled inside of the default case
363	/// formatting.
364	fn handle_switch_default_case_comment(
365	    comment: DecoratedComment<JsLanguage>,
366	) -> CommentPlacement<JsLanguage> {
367	    if comment.enclosing_node().kind() != JsSyntaxKind::JS_DEFAULT_CLAUSE {
368	        return CommentPlacement::Default(comment);
369	    }
370	
371	    if !comment.kind().is_line() {
372	        return CommentPlacement::dangling(comment.enclosing_node().clone(), comment);
373	    }
374	
375	    let Some(block) = comment
376	        .following_node()
377	        .and_then(JsBlockStatement::cast_ref)
378	    else {
379	        if comment.preceding_node().is_some() {
380	            return CommentPlacement::Default(comment);
381	        }
382	        return CommentPlacement::dangling(comment.enclosing_node().clone(), comment);
383	    };
384	
385	    place_block_statement_comment(block, comment)
386	}
387	
388	fn handle_labelled_statement_comment(
389	    comment: DecoratedComment<JsLanguage>,
390	) -> CommentPlacement<JsLanguage> {
391	    match comment.enclosing_node().kind() {
392	        JsSyntaxKind::JS_LABELED_STATEMENT => {
393	            CommentPlacement::leading(comment.enclosing_node().clone(), comment)
394	        }
395	        _ => CommentPlacement::Default(comment),
396	    }
397	}
