/// Keeps trailing line comments on a `case` clause line on the same line as the
/// `case` keyword, instead of moving them into the clause's block statement.
///
/// A `case` clause whose consequent is a single block statement hugs the block
/// on the same line as the `case`:
///
/// ```javascript
/// switch (x) {
///   case 1: // comment
///   case 2: { // comment
///     doWork();
///   }
/// }
/// ```
///
/// On the first format pass the comment sits between the `:` and the `{` (its
/// enclosing node is the [`JsCaseClause`]). Once the block hugs the case line,
/// subsequent passes see the comment right after the `{`, so its enclosing node
/// becomes the [`JsBlockStatement`]. In both situations the comment is made a
/// trailing comment of the clause's test so that it stays on the `case` line and
/// the formatter remains idempotent, rather than being pulled into the block
/// body as a leading comment of the first statement.
fn handle_switch_case_comment(
    comment: DecoratedComment<JsLanguage>,
) -> CommentPlacement<JsLanguage> {
    if !comment.kind().is_line() {
        return CommentPlacement::Default(comment);
    }

    let enclosing = comment.enclosing_node();

    let case_clause = match enclosing.kind() {
        // First pass: the comment is between the `:` and the block statement.
        JsSyntaxKind::JS_CASE_CLAUSE
            if comment
                .following_node()
                .is_some_and(|following| JsBlockStatement::can_cast(following.kind())) =>
        {
            JsCaseClause::cast_ref(enclosing)
        }
        // Subsequent passes: the block hugs the case line, so the comment now
        // sits right after the `{` of the clause's block statement.
        JsSyntaxKind::JS_BLOCK_STATEMENT if comment.preceding_node().is_none() => enclosing
            .parent()
            .filter(|list| list.kind() == JsSyntaxKind::JS_STATEMENT_LIST)
            .and_then(|list| list.parent())
            .and_then(JsCaseClause::cast),
        _ => None,
    };

    let Some(case_clause) = case_clause else {
        return CommentPlacement::Default(comment);
    };

    // Only clauses whose consequent is a single hugging block statement print
    // the block on the `case` line, so this handling only applies to them.
    let mut consequent = case_clause
        .consequent()
        .iter()
        .filter(|statement| !matches!(statement, AnyJsStatement::JsEmptyStatement(_)));
    let is_single_block_statement = matches!(
        consequent.next(),
        Some(AnyJsStatement::JsBlockStatement(_))
    ) && consequent.next().is_none();

    if !is_single_block_statement {
        return CommentPlacement::Default(comment);
    }

    match case_clause.test() {
        Ok(test) => CommentPlacement::trailing(test.into_syntax(), comment),
        Err(_) => CommentPlacement::Default(comment),
    }
}

